export const helpArticles = helpCategories.flatMap(category => category.guides.map(article => ({
  ...article, categoryId: category.id, categoryTitle: category.title,
  href: article.href || category.href, ownerOnly: Boolean(article.ownerOnly || category.ownerOnly),
})));

export function searchHelp(query = '', categoryId = 'all') {
  const words = query.toLowerCase().trim().split(/\s+/).filter(Boolean);
  return helpArticles.filter(article => {
    if (categoryId !== 'all' && article.categoryId !== categoryId) return false;
    const text = [article.title, article.purpose, article.categoryTitle, ...article.steps, article.note || '', article.example || ''].join(' ').toLowerCase();
    return words.every(word => text.includes(word));
  });
}
